// Credits to the online graph that I found: https://www.desmos.com/calculator/mlggcjbxpo
int Prime(int x) {
    int sum = 0;
    for (int i = 2; i < x-1; i++) {
    float div = float(x)/float(i);
    sum += ( div == round(div) ? 1 : 0 );
    }
    return ( sum < 1 ? 1 : 0 );
}
ivec2 Prime(ivec2 v) { return ivec2(Prime(v.x), Prime(v.y)); }

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv *= iResolution.xy/4.0;

    ivec2 uvF = ivec2(floor(uv));
    vec3 col = vec3(uvF*Prime(uvF), 0);

    // Output to screen
    fragColor = vec4(col,1.0);
}
